insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shimo-song', '世末歌者', '乐正绫', 'COP', '2016-08-25', 'https://www.bilibili.com/video/BV1Qs411k7Qv', NULL, '["神话曲","最慢中V神话曲"]'::jsonb, '流浪歌手阿绫与神灵立下赌约，在重复湮灭的世界中孤独歌唱，寻找愿意共赴终结的共鸣者。', 'shimo', '{"plays":500,"asOf":"2023-10-14","note":"快照 500万，其后达成神话曲（约2026-04，待核）","milestone":"站内播放最高的单曲 · 中V 史上最慢达成的神话曲"}'::jsonb, '[{"image":"assets/panels/shimo-p1.jpg","caption":"我仍然在无人问津的阴雨霉湿之地，和着雨音，唱着没有听众的歌曲。"},{"image":"assets/panels/shimo-p2.jpg","caption":"神灵与流浪歌手阿绫立下赌约：若末日之世有人愿与她共赴死亡，世界便得以延续。"},{"image":"assets/panels/shimo-p3.jpg","caption":"轮回开始，世界一次又一次走向终结，歌声始终没有等到回应。"},{"image":"assets/panels/shimo-p4.jpg","caption":"人潮漫无目的地散去，只有一个女孩每次驻足片刻，便又离去。"},{"image":"assets/panels/shimo-p5.jpg","caption":"曲终之时，人们终于停止寻觅，在滂沱的世末之雨中乞求着奇迹。"},{"image":"assets/panels/shimo-p6.jpg","caption":"颤抖的双手被牵起，迎来每个人的结局——2018 COMING SOON。（注：因专辑跳票至今，成为中V圈著名冥场面，本仓库名即玩此梗）"}]'::jsonb, '[{"label":"投稿B站","date":"2016-08-25"},{"label":"100万播放 · 传说曲","date":"2018-03-24"},{"label":"200万播放","date":"2020-04-08"},{"label":"500万播放","date":"2023-10-14"},{"label":"神话曲（用时3509日，最慢中V神话曲）","date":"约2026-04（快照待核）"}]'::jsonb, '（待补：第一次听到这首歌的场景、为什么项目文件夹叫「世末歌者」——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('xiafeng', '夏风', '洛天依', 'COP', '2012-07-27', 'https://www.bilibili.com/video/av320115', NULL, '["殿堂曲","系列首作"]'::jsonb, '系列的原点，也是 COP 初三毕业时的出道曲：某个世界里的天依站在楼顶俯瞰市井，动过逃走的念头，最后还是决定勇敢面对。', 'shimo', NULL, '[{"caption":"一阵不属于这个季节的风吹来，天依站在城市高处，俯瞰着市井的万家灯火。"},{"caption":"面对挫折她动过逃走的念头，却在风里闻见了故乡的槐米味道。"},{"caption":"灯几乎要熄灭，却仍不甘隐于黑夜；她决定带着满身泥泞，朝夏风飞去的方向一直走下去。"}]'::jsonb, '[{"label":"初版投稿B站（av320115）· 系列首作 / COP 出道曲","date":"2012-07-27"},{"label":"重制版投稿B站（av403127，奇音工作社出品）","date":"2012-11-27"},{"label":"殿堂曲（初版用时 4807 日，曾为中文VOCALOID最慢殿堂曲）","date":"殿堂达成日待核"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shimo-jiyuyun', '世末积雨云', '洛天依', 'COP', '2014-10-02', 'https://www.bilibili.com/video/av1579079', NULL, '["传说曲","系列第二作"]'::jsonb, '碌碌无为、一味逃避现实的她，在布满积雨云的世末抬头仰望天空崩塌——直到最后一分钟，才察觉那片蔚蓝有多动人。', 'shimo', '{"plays":240.08,"asOf":"2026-10-11","note":"快照 240.08万；来源萌娘百科条目，待B站投稿页核实"}'::jsonb, '[{"caption":"末日来临，天依伫立在滂沱的世末之雨中，抬头仰望积雨云的崩塌。"},{"caption":"曾经一味逃避的她，忽然察觉记忆中蔚蓝天空的动人——但一切就要结束了。"},{"caption":"无名的歌者在充斥恐惧的市井中淡然微笑，静待终结的钟声敲响。"}]'::jsonb, '[{"label":"投稿B站（av1579079）","date":"2014-10-02 09:36"},{"label":"传说曲 · 播放 240.08万（用时 3345 日）","date":"2023-11-29 21:42"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('huiyin', '回音', '洛天依', 'COP', '2015-08-10', 'https://www.bilibili.com/video/av2711298', NULL, '["殿堂曲","系列第三作"]'::jsonb, '空旷的房间里天依独自歌唱，应答她的只有在暮光中交织的回音——看似悠然自得，其实是窒息般的孤独。', 'shimo', '{"plays":52.59,"asOf":"2026-10-11","note":"快照 52.59万；来源 VCPedia 条目，待B站投稿页核实"}'::jsonb, '[{"caption":"雨幕中的街角，风铃声模糊，足迹已被冲刷殆尽。"},{"caption":"只有回音在房间里旋转，与暮光交织，将孤独的歌声拥入怀中。"},{"caption":"星点的回音汇成声浪，一次又次叩响她的心房。"}]'::jsonb, '[{"label":"投稿B站（av2711298）· 系列第三作 / 失踪一年后的回归作","date":"2015-08-10"},{"label":"殿堂曲 · 播放 52.59万","date":"快照 2026-10-11（达成日待核）"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('tonggui-shijiexian', '同归世界线', '乐正绫', 'COP', '2015-09-11', NULL, '本曲投稿于 5sing，B站无正式投稿页，故不提供B站链接（不编造来源）', '[]'::jsonb, '串联起整个系列的一曲：这一次的世界线里，终焉降临之时有人与她一同面对——终结不再是孤身一人的结局。', 'shimo', NULL, '[{"caption":"古旧生锈的钟无感情地拍打着回声，世界线又一次变动、定格。"},{"caption":"在被剥离了色彩的世界里，她仍在寻觅那一点泛黄的奇迹。"},{"caption":"轰鸣的钟声渐近，泪滴混着凉雨向未来延伸——这世界线不再终于孤寂。"}]'::jsonb, '[{"label":"投稿 5sing（B站无正式投稿页）","date":"2015-09-11"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('hello-bye-days', 'hello&bye,days', '洛天依', 'COP', '2015-12-17', 'https://www.bilibili.com/video/av3402945', NULL, '["传说曲","系列第四作"]'::jsonb, '昏暗的雨夜，失恋的天依用酒精麻醉自己，拨出烂熟的号码只等到忙音；她蜷在窗台听见阿绫的歌声，目光却越过她，散在自己的悲伤里。', 'shimo', '{"plays":108.1,"asOf":"2025-09-13","note":"快照 108.1万；来源百度百科条目（截至2025-09-13），待B站投稿页核实"}'::jsonb, '[{"caption":"三步并作两步走，逃离喧嚣的街头；拨出烂熟的号码，忙音在人海中轻轻叩响。"},{"caption":"漆黑的夜幕中她蜷缩在冰冷的窗台，无意间听见了阿绫的歌声。"},{"caption":"目光越过歌者、散在自己的悲伤里，终焉的信号随那歌声一起发出。（PV 末尾 4:15 后是《世末歌者》的预告）"}]'::jsonb, '[{"label":"投稿B站（av3402945）","date":"2015-12-17 22:28"},{"label":"传说曲 · 播放 108.1万（用时 3397 日）","date":"2025-04-06 15:42"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('liangyu', '凉雨', '洛天依', 'COP', '2017-02-23', 'https://www.bilibili.com/video/av8786522', NULL, '["传说曲","系列第六作"]'::jsonb, '高楼坠落的砖砾将天依狠狠拍在地面。弥留的幻觉里，那个围着红围巾的女孩在她身边坐下，弹起吉他，像献上一曲挽歌。', 'shimo', '{"plays":122.85,"asOf":"2026-10-11","note":"快照 122.85万（VCPedia）；萌娘UK记为殿堂曲119.74万，冲突待B站核实"}'::jsonb, '[{"caption":"城市从高处坍塌，砖砾雨点般落下，将她狠狠拍在地面。"},{"caption":"恍惚中，围着红围巾的女孩在她身边坐下，眼中带着悲悯，弹起吉他。"},{"caption":"弥留之际她在前世记忆的指引下追上那个红衣女孩——画面定格在灿烂晴空下缓缓靠近的两人。"}]'::jsonb, '[{"label":"投稿B站（av8786522）","date":"2017-02-23 18:28"},{"label":"传说曲（用时 3107 日20时30分）","date":"2025-08-28 14:58"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('suimeng', '碎梦', '乐正绫', 'COP', '2026-04-05', 'https://www.bilibili.com/video/BV1sKSSBKEK8', NULL, '["ACE殿堂曲","系列最新作"]'::jsonb, '系列等了九年的「整梦」：在《世末歌者》达成神话的当天夜里，阿绫抱着木吉他，把自己的故事娓娓弹唱出来。', 'shimo', NULL, '[{"caption":"又小又拥挤的房间，堆满贪念的床边，折成纸飞机的传单上画着潦草的未来。"},{"caption":"四处虫鸣的夏夜、潮湿安静的街边，那个笨拙打着拍子的陌生人，都不见了。"},{"caption":"被打碎的梦想重新拼凑——她抱着碎块，让停摆的时针重新开始摇摆。"}]'::jsonb, '[{"label":"Short 版发布（网易云 / B站音频，VOCALOID 声库）","date":"2017-10-29"},{"label":"完整版投稿B站（BV1sKSSBKEK8）· 与《世末歌者》神话同日","date":"2026-04-05"},{"label":"ACE殿堂曲（用时 14 时 44 分）","date":"2026-04-06 11:44"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('liwu', '礼物', '洛天依', 'COP', '2013-08-14', NULL, '本曲投稿于 5sing（原版 2013-08-14 / 重置版 2015-10-05），B站无正式投稿页，故不提供B站链接（不编造来源）', '[]'::jsonb, '一个试图守住本真的孩子，在枯槁而生涩的世界里什么都无法撼动，只能看着幼时的自己迫不及待地长大——这份湿漉漉的成长，是一份强人所难、签收便无法退换的礼物。', 'shimo', NULL, '[{"caption":"孩子攥着不肯松手的本真，在灰扑扑的世界里笨拙地抵挡。"},{"caption":"枯槁而生涩的岁月里，什么都撼动不了，只有时间在悄悄挪移。"},{"caption":"幼时的自己迫不及待地长大——这份湿漉漉的成长，签收便无法退换。"}]'::jsonb, '[{"label":"原版投稿 5sing","date":"2013-08-14"},{"label":"重置版投稿 5sing","date":"2015-10-05"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('xiayekong', '夏夜空', '洛天依', 'COP', '2014-09-08', NULL, '本曲投稿于 5sing（2014-09-08），B站无正式投稿页，故不提供B站链接（不编造来源）', '[]'::jsonb, 'COP 较为抒情的早期作品：天依梦中有一片绚烂夜空与思念的人，「花火」「瞳孔」「苍穹」关系的两次转变串联全曲，写尽她对世界的浪漫幻想如何逐渐现实化，结尾转为对思念之人与儿时憧憬的追忆。', 'shimo', NULL, '[{"caption":"天依梦见一片绚烂夏夜空，和那个思念的人。"},{"caption":"花火藉由瞳孔投影到苍穹，她对世界的浪漫幻想一次次转变。"},{"caption":"多日的阴雨之后，幻想褪色，只剩对故人与儿时憧憬的追忆。"}]'::jsonb, '[{"label":"投稿 5sing（无B站正式投稿页）","date":"2014-09-08"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('nova', 'NOVA', '洛天依、言和、乐正绫', 'DELA（曲）· 雨狸（策划/词）', '2015-11-14', 'https://www.bilibili.com/video/av3217323', NULL, '["序曲"]'::jsonb, '妄想症系列先行概念曲：泠珞与零羽的乐队通过海选、梦想将启，挚友却不明不白地离开——一切妄想的起点。', 'wangxiang', NULL, '[{"caption":"第五音高中，泠珞与零羽组成乐队 VividCycle，词曲与吉他相遇，向着比赛海选进发。"},{"caption":"海选通过了。舞台灯光亮起，梦想仿佛触手可及。"},{"caption":"然而零羽却不明不白地离开了，没有留下任何解释。"},{"caption":"遭受巨大打击的泠珞，世界开始出现裂痕。"},{"caption":"妄想的幕布就此拉开——重重世界的大门，缓缓打开。"}]'::jsonb, '[{"label":"投稿B站（av3217323）· 系列先行概念曲","date":"2015-11-14"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('yichong-jiahai', '一重加害', '洛天依、言和', 'DELA（曲）· 雨狸（策划/词）', '2015-11-28', 'https://www.bilibili.com/video/av3291729', NULL, '["传说曲"]'::jsonb, '对应「被害妄想」。音乐附中生泠珞被无处不在的黑影缠上，妄想终于化为追杀她的加害者颜语——系列正篇首作。', 'wangxiang', '{"plays":292.36,"asOf":"2024-09-07","note":"最终记录快照，其后视频换源纯音乐","milestone":"妄想症系列正篇首作 · 传说曲"}'::jsonb, '[{"image":"assets/panels/yichong-p1.jpg","caption":"几个月来，音乐附中学生泠珞时时刻刻感觉，身后有一个无处不在的黑影想要谋害她。"},{"image":"assets/panels/yichong-p2.jpg","caption":"她开始对周遭的一切神经质般地戒备，日常变得风声鹤唳。"},{"image":"assets/panels/yichong-p3.jpg","caption":"终于，妄想中的黑影实质化为加害者——颜语，对她展开追杀。"},{"image":"assets/panels/yichong-p4.jpg","caption":"风声鹤唳的日常里，逃亡成了她的全部。"},{"image":"assets/panels/yichong-p5.jpg","caption":"墙上贴着一张海报：那个叫零羽的人、失去的音乐兴趣、被遗忘的记忆——伏笔就藏在这里。"},{"image":"assets/panels/yichong-p6.jpg","caption":"故事在巨大悬念中收束，为整个系列的结局埋下了隐秘的伏笔。"}]'::jsonb, '[{"label":"投稿B站（av3291729）","date":"2015-11-28"},{"label":"传说曲 · 播放 292.36万（最终记录快照，其后视频换源纯音乐）","date":"2024-09-07（最终记录）"}]'::jsonb, '（待补：第一次听到这首歌的场景与感想——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('erzhong-biange', '二重变革', '洛天依、言和', 'DELA（曲）· 雨狸（策划/词）', '2015-12-12', 'https://www.bilibili.com/video/av3370007', NULL, '[]'::jsonb, '对应「物理影响妄想·逆」。泠珞获得凭想象改变现实的能力反抗加害者，却发现幻想的产物杀不死——直到她找到弱点。', 'wangxiang', NULL, '[{"caption":"加害者颜语宣告：顺从你的愿望——由我来杀死你自己。"},{"caption":"泠珞试图反抗，却发现自己也获得了凭借想象改变现实的能力。"},{"caption":"然而加害者同是自己幻想的产物，无论如何都杀不死。"},{"caption":"泠珞找到她的弱点，布下激光陷阱，举起格洛克。"},{"caption":"加害者倒下了——但妄想世界，并没有因此终结。"}]'::jsonb, '[{"label":"投稿B站（av3370007，后未回归）","date":"2015-12-12"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('sanzhong-ailian', '三重爱恋', '洛天依、言和', 'DELA（曲）· 雨狸（策划/词）', '2016-01-28', 'https://www.bilibili.com/video/av3683320', NULL, '[]'::jsonb, '对应「情爱妄想」。掩埋恐怖记忆的泠珞虚构出温柔的守护者，坠入热恋——直到潜意识苏醒，怀疑悄然生根。', 'wangxiang', NULL, '[{"caption":"掩埋一二重的可怖记忆，泠珞试图回到盲目而平静的生活。"},{"caption":"对安宁与保护的渴望，让她虚构出温柔的守护者颜语。"},{"caption":"一见钟情，两人陷入热恋——青色的妄想世界看似完美。"},{"caption":"然而潜意识泠珞苏醒了：眼前的「现实」与过去的记忆开始对不上。"},{"caption":"熟悉的容貌令她心生疑窦——守护者与加害者，为何如此相似？"}]'::jsonb, '[{"label":"投稿B站（av3683320）","date":"2016-01-28"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('sizhong-zuinie', '四重罪孽', '洛天依、言和、乐正绫', 'DELA（曲）· 雨狸（策划/词）', '2016-03-26', 'https://www.bilibili.com/video/av4188543', NULL, '[]'::jsonb, '对应「自罪妄想」。泠珞想起被自己掩盖的事实，明白恋人只是妄想，在自我审判的边缘被零羽的记忆唤回——加害者却因此重生。', 'wangxiang', NULL, '[{"caption":"被掩盖的事实终于浮出水面：眼前的恋人，只是自己的妄想。"},{"caption":"泠珞为自己的罪孽痛苦不已，守护者却发现异样，发誓要保护她。"},{"caption":"她企图以死赎罪——关于零羽的记忆被唤醒，让她失去了勇气。"},{"caption":"恐惧与痛苦滋蔓，坠落的加害者颜语，再度重生。"},{"caption":"一层层向下穿越，这一次，来到了第四重世界。"}]'::jsonb, '[{"label":"投稿B站（av4188543）","date":"2016-03-26"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('wuzhong-kongdong', '五重空洞', '洛天依、乐正绫', 'DELA（曲）· 雨狸（策划/词）', '2016-04-28', 'https://www.bilibili.com/video/av4492594', NULL, '[]'::jsonb, '对应「内心被洞悉感」。彼岸花田深处，潜意识泠珞找到了被掩埋的零羽——怀中却只剩枯骨。坠落之章在此收束。', 'wangxiang', NULL, '[{"caption":"潜意识泠珞走进彼岸花田，寻找埋葬在记忆深处的零羽。"},{"caption":"她试图抱紧曾经的挚友，怀中却只剩下一截枯骨。"},{"caption":"过去的美好记忆漫上心头，更映衬出生离死别的悲恸与迷茫。"},{"caption":"零羽胸前的红色流苏一闪而过——关键物象，就此埋下。"},{"caption":"她渴望找到办法，拯救陷于重重梦境中的自己。坠落之章，至此收束。"}]'::jsonb, '[{"label":"投稿B站（av4492594）","date":"2016-04-28"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('liuzhong-buzhong', '六重不忠', '洛天依、言和、乐正绫', 'DELA（曲）· 雨狸（策划/词）', '2016-08-05', 'https://www.bilibili.com/video/av5656549', NULL, '[]'::jsonb, '对应「嫉妒妄想」。加害者策反守护者同赴五重世界，守护者却为泠珞挡下刀剑，化作零羽的流苏——嘱诫随泪落下。', 'wangxiang', NULL, '[{"caption":"加害者击败并策反了守护者，二人一同前往五重世界。"},{"caption":"见到零羽的囚所前，泠珞为零羽与守护者的「背叛」痛苦万分。"},{"caption":"刀剑加身的瞬间，守护者为泠珞挡下了加害者的攻击。"},{"caption":"守护者化作一串朱红色流苏——那是零羽留给泠珞的温暖。"},{"caption":"泠珞接住流苏，听到了零羽殷切的嘱诫。"}]'::jsonb, '[{"label":"投稿B站（av5656549）","date":"2016-08-05"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('qizhong-gubing', '七重痼病', '洛天依、言和、乐正绫', 'DELA（曲）· 雨狸（策划/词）', '2016-12-16', 'https://www.bilibili.com/video/av7549517', NULL, '["传说曲"]'::jsonb, '对应「疑病妄想」。天台上真相重演，加害者刺穿潜意识，却换来同归于尽——妄想世界摇摇欲坠，苏醒近在眼前。', 'wangxiang', NULL, '[{"caption":"明白真相的泠珞逃回第五音，终于登上了天台。"},{"caption":"零羽坠落的场景在眼前重演——原来这才是最初的伤口。"},{"caption":"加害者挟持了潜意识泠珞：忘掉零羽，永远沉沦在妄想世界。"},{"caption":"刀刃刺穿潜意识，却换来同归于尽的结局。"},{"caption":"妄想世界摇摇欲坠，泠珞面临孤独的苏醒。"}]'::jsonb, '[{"label":"投稿B站（av7549517，殿堂用时约44小时）","date":"2016-12-16"},{"label":"传说曲 · 播放 244.28万（最终记录快照）","date":"2024-09-07（最终记录）"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('bazhong-huigui', '八重回归', '洛天依、乐正绫', 'DELA（曲）· 雨狸（策划/词）', '2017-03-10', 'https://www.bilibili.com/video/av9072485', NULL, '["传说曲"]'::jsonb, '对应「初始妄想」。泠珞从妄想中苏醒回归现实，却再难接受挚友离去——一切似乎恢复正常，只是这个世界已再无色彩。', 'wangxiang', NULL, '[{"caption":"泠珞终于从妄想中苏醒，回归现实世界。"},{"caption":"她仍无法接受挚友离去的事实，抑郁中甚至试图割腕。"},{"caption":"最终她妥协于现实，淡漠了曾经的爱恋与梦想，尝试平淡度日。"},{"caption":"一切似乎都恢复正常——只是，这个世界已再无色彩。"},{"caption":"投稿七天后，本曲换源为「八重回归·真」，歌词与PV皆有不同——结局另有变动。"}]'::jsonb, '[{"label":"投稿B站（av9072485）","date":"2017-03-10"},{"label":"换源版「八重回归·真」上线，暗示结局变动","date":"2017-03-16"},{"label":"传说曲 · 播放 200.69万（最终记录快照）","date":"2024-09-07（最终记录）"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('jiuzhong-xianshi', '九重现实', '洛天依、乐正绫', 'DELA（曲）· 雨狸（策划/词）', '2017-03-17', 'https://www.bilibili.com/video/av9214515', NULL, '["传说曲"]'::jsonb, '系列真·终曲：整个故事的真正剧情脉络就此揭开，空白的世界等待重新着色——泠珞接受一切，走向带有希望的未来。', 'wangxiang', '{"plays":282.33,"asOf":"2024-09-07","note":"最终记录快照","milestone":"妄想症系列完结作 · 传说曲"}'::jsonb, '[{"caption":"系列终曲：整个故事的真正剧情脉络，在此揭开。"},{"caption":"妄想与现实的对峙迎来终点，白色，也许是可以着色的，也许是被擦除了色彩之后的。"},{"caption":"「我所描述的一切或许并非真实，然而我的感受绝无虚假。」——绝无虚假。"},{"caption":"泠珞接受一切，故事呈现出带有希望的未来。"},{"caption":"面对凶险的今后——九重落幕，现实开始。"}]'::jsonb, '[{"label":"投稿B站（av9214515）· 系列完结作","date":"2017-03-17"},{"label":"传说曲 · 播放 282.33万（最终记录快照）","date":"2024-09-07（最终记录）"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('lingchong-qiyuan', '零重祈愿', '乐正绫', '崩坏（曲）· 雨狸（策划/词）· DELA（代投）', '2017-02-25', 'https://www.bilibili.com/video/av8815372', NULL, '["角色歌"]'::jsonb, '对应「还原之章·零羽」。零羽外表开朗，背后却是混乱破碎的家庭——乐队通过海选、生日收到项链的喜悦后，回家却看见举着菜刀疯了的母亲。混乱中母亲割伤了她的手，她再也无法弹吉他，默默退出比赛、转身退场。这是整系列妄想发生前的开端，也是结局的伏笔。', 'wangxiang', NULL, '[{"caption":"零羽外表开朗，是乐队 VividCycle 的吉他手兼主唱，承载着所有人的期待。"},{"caption":"乐队通过海选，生日那天还收到了泠珞的项链，一切都那么开心。"},{"caption":"可当她揣着通知书笑着回到家时，看到的是举着菜刀、已然疯了的母亲。"},{"caption":"混乱中母亲割伤了她的手——她再也无法弹吉他。"},{"caption":"她再也坚持不下去，默默退出比赛，转身退场。这是整系列妄想发生前的开端。"}]'::jsonb, '[{"label":"投稿B站（av8815372）· 零羽的还原之章·角色歌","date":"2017-02-25"},{"label":"传说曲 · 播放 183.51万（2022-01-08 达成）","date":"2022-01-08"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('sanzhong-lianai', '三重恋爱', '言和', 'DELA（曲）· 雨狸（策划/词）', '2016-02-05', 'https://www.bilibili.com/video/av3761912', NULL, '["角色歌"]'::jsonb, '对应「还原之章·偶像颜语」。现实中偶像颜语的成名曲，在小说中出现：颜语是第五音高中最叛逆的学生，毕业后被生活所迫提前出道；她从小就被贴上不符的标签、遭人议论，却意志坚定地用行动反抗世界对她的束缚。', 'wangxiang', NULL, '[{"caption":"颜语是第五音高中最叛逆的学生，外表张扬、不甘被定义。"},{"caption":"毕业后被生活所迫提前出道，成为现实中叛逆的偶像。"},{"caption":"从小被贴上不符的标签、遭人议论，她却意志坚定，用行动反抗世界对自己的束缚。"}]'::jsonb, '[{"label":"投稿B站（av3761912）· 偶像颜语的角色歌（还原之章）","date":"2016-02-05"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('linchong-qiyuan', '泠重乞愿', '洛天依', 'DELA（曲）· 雨狸（策划/词）', '2016-05-20', 'https://www.bilibili.com/video/av4704894', NULL, '["角色歌","传说曲"]'::jsonb, '对应「还原之章·♮之章.泠珞」。泠珞的歌无人问津，甚至遭到抄袭；当她几乎对这个世界失去期待时，得到了仰慕的歌手零羽的理解与接纳，两人组建乐队、通过海选。然而零羽不告而别，泠珞陷入悲痛与空洞，开始怀疑自我价值，从而坠入妄想逃避现实。这是整系列妄想发生前、泠珞的现实开端。', 'wangxiang', NULL, '[{"caption":"泠珞的歌无人问津，甚至遭到抄袭，几乎对这个世界失去期待。"},{"caption":"她得到了仰慕的歌手零羽的理解与接纳，两人组建乐队、通过海选。"},{"caption":"然而零羽不告而别，泠珞陷入悲痛与空洞，开始怀疑自我价值——妄想由此而生。"}]'::jsonb, '[{"label":"投稿B站（av4704894）· 泠珞的还原之章·角色歌","date":"2016-05-20"},{"label":"传说曲（具体达成日期待核）","date":"待核"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('zigongzishou', '自攻自受', '言和', '崩坏（曲/编）· 雨狸（策划/词）· DELA（代投）', '2016-10-01', 'https://www.bilibili.com/video/av6477673', NULL, '["番外","传说曲"]'::jsonb, '对应「妄想世界·双颜语」。独立番外，不隶属任何一章；时间点在四重之后、六重之前，描绘加害者颜语与守护者颜语的厮杀之战。诡异又热血的曲调，展现二者对立冲突与矛盾和谐——也揭示了六重中加害者成功策反守护者的深层原因。', 'wangxiang', NULL, '[{"caption":"独立番外，时间线在四重与六重之间。"},{"caption":"加害者颜语与守护者颜语——同一个人的两面——展开厮杀。"},{"caption":"诡异又热血的曲调，揭示二者对立统一的矛盾本质，也藏着六重策反的伏笔。"}]'::jsonb, '[{"label":"投稿B站（av6477673）· 番外篇（双颜语）","date":"2016-10-01"},{"label":"传说曲（具体达成日期待核）","date":"待核"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('wangxiang-paranoia', '妄想Paranoia', '洛天依、言和、乐正绫', 'DELA（曲）· 雨狸（策划/词）', '2017-01-28', 'https://www.bilibili.com/video/av8264026', NULL, '["番外"]'::jsonb, '系列番外串烧：将各曲 Remix 并重调教的串烧作品，把七个原本风格节奏迥异的旋律连成一个整体重新编曲。', 'wangxiang', NULL, '[{"caption":"系列番外篇，一首 Remix 串烧作品。"},{"caption":"把七个原本风格、节奏都不同的旋律连在一起，当作一个整体重新编曲。"}]'::jsonb, '[{"label":"投稿B站（av8264026）· 番外串烧","date":"2017-01-28"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('wangxiang-reality', '妄想Reality', '洛天依、言和、乐正绫', 'DELA（曲/编）· 雨狸（策划/词）', '2017-12-27', 'https://www.bilibili.com/video/av17679245', NULL, '["番外"]'::jsonb, '系列番外篇，是《妄想Paranoia》的重填词版本（Reality 增加了还原之章、八重与九重的旋律），回避以往所有曲子用过的意象，呈现一种全新的意境。', 'wangxiang', NULL, '[{"caption":"系列番外篇，是《妄想Paranoia》的重填词版本。"},{"caption":"Reality 增加了还原之章、八重与九重的旋律，回避旧有意象，呈现全新意境。"}]'::jsonb, '[{"label":"投稿B站（av17679245）· 番外重填词","date":"2017-12-27"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shuangxiang-sinian', '双向思念', '洛天依、言和', 'JUSF周存（曲/词/编）· sya（绘/PV）', '2013-11-26', 'https://www.bilibili.com/video/av850424', NULL, '["正篇","殿堂曲"]'::jsonb, '双向系列第一世（首作）。洛天依与言和相遇、相恋，却因自觉身份卑微而放弃；言和误以为她不爱自己，为试探而假装爱上乐正绫。洛天依一时冲动杀害言和，悔恨中自语「若时间可以重来」，随即自杀——第一世化为梦境，轮回转入第二世。', 'shuangxiang', NULL, '[{"image":"assets/panels/shuangxiang-sinian-p1.jpg","caption":"洛天依与言和相遇、相恋，却因自觉身份卑微而不敢接受。"},{"image":"assets/panels/shuangxiang-sinian-p2.jpg","caption":"言和误以为她不爱自己，为试探而假装爱上乐正绫。"},{"image":"assets/panels/shuangxiang-sinian-p3.jpg","caption":"洛天依冲动之下杀害言和，悔恨中自语「若时间可以重来」随即自杀——第一世化为梦境。"}]'::jsonb, '[{"label":"投稿B站（av850424）· 系列第一世·首作","date":"2013-11-26"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shuangxiang-kuayue', '双向跨越', '洛天依、言和', 'JUSF周存（曲/词/编）· sya（绘/PV）', '2013-12-04', 'https://www.bilibili.com/video/av859925', NULL, '["正篇","殿堂曲"]'::jsonb, '双向系列第二世（第一种结局）。剧情前半与《双向思念》相同，但洛天依举刀刺向言和时，被言和紧紧抱住、表白心意，两人幸福相守。然而《单向宣战》结局里《双向跨越》的CG被描红，表明这只是假结局；真正的第二世结局是《单向宣战》。', 'shuangxiang', NULL, '[{"caption":"第二世展开，前半与首作相同。"},{"caption":"洛天依举刀之时，言和紧紧抱住她、表白心意。"},{"caption":"两人幸福相守——但这是被《单向宣战》描红的假结局。"}]'::jsonb, '[{"label":"投稿B站（av859925）· 系列第二世·第一种结局","date":"2013-12-04"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('danxiang-xuanzhan', '单向宣战', '言和', 'JUSF周存（曲/词/编/调）· sya（绘/PV）', '2013-12-12', 'https://www.bilibili.com/video/av869576', NULL, '["正篇","殿堂曲"]'::jsonb, '双向系列第二世 TRUE END（真正结局）。紧接《双向跨越》言和天依互表心意之后：乐正绫认定是洛天依抢走了深爱的言和，疯狂报复并将她引向自杀。因创作时乐正绫声库未发布，本曲初由言和代唱（乐正绫视角），声库发布后换源重调。', 'shuangxiang', NULL, '[{"caption":"第二世真正结局，紧接《双向跨越》之后。"},{"caption":"乐正绫认定洛天依抢走了言和，疯狂报复。"},{"caption":"乐正绫将洛天依引向自杀——「你毕竟给予过她从未感受过的温暖」。"}]'::jsonb, '[{"label":"投稿B站（av869576）· 系列第二世·TRUE END","date":"2013-12-12"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shuangxiang-xingfu', '双向幸福', '洛天依、言和', 'JUSF周存（曲/词/编/调）· sya（绘/PV）', '2013-12-27', 'https://www.bilibili.com/video/BV19s411o7JZ', NULL, '["正篇","殿堂曲"]'::jsonb, '双向系列第三世。建立在之前三作基础上：言和为试探洛天依是否爱他，与乐正绫佯装情侣后又抛弃她；乐正绫为复仇假扮言和离间洛天依。洛天依伤心欲自杀时，乐正绫不忍爱人伤心而悔悟，阻止了她并坦白，随即跳楼自杀。洛天依对言和的误会化解，两人重归于好。', 'shuangxiang', NULL, '[{"caption":"第三世，建立在前三作基础上。"},{"caption":"言和佯装与乐正绫相恋试探天依；乐正绫为复仇假扮言和离间天依。"},{"caption":"天依欲自杀时，乐正绫悔悟阻止并坦白，随即跳楼；两人误会化解、重归于好。"}]'::jsonb, '[{"label":"投稿B站（BV19s411o7JZ）· 系列第三世","date":"2013-12-27"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shuangxiang-jianjin', '双向监禁', '洛天依、言和', 'JUSF周存（曲/词/编/调）· sya（绘/PV）', '2014-01-10', 'https://www.bilibili.com/video/BV1Ds411o7Yd', NULL, '["正篇","殿堂曲"]'::jsonb, '双向系列第四世/第五世。剧情一般认为与前作《双向幸福》无关，由第二世乐正绫在《单向宣战》结尾所想「如果时间可以重来」延续而来：洛天依亲手杀掉乐正绫后写信约言和到天台；言和发现后精神崩溃报警，被送进精神病院，洛天依因杀人被关进拘留所——「双向监禁」即一人入狱、一人入院。本曲黑化曲风与血腥画面，是系列点击量与收藏最高的曲目之一。', 'shuangxiang', NULL, '[{"caption":"时间轴位于言和与乐正绫假装恋爱的时期。"},{"caption":"洛天依杀掉乐正绫后写信约言和到天台。"},{"caption":"言和崩溃报警被送进精神病院，天依因杀人入狱——「双向监禁」。"}]'::jsonb, '[{"label":"投稿（专辑《双向·轮回与幸福》）· 系列第四/五世","date":"2014-01-10"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shuangxiang-yiwang', '双向遗忘', '洛天依、言和、乐正绫', 'JUSF周存（曲/词/编/调）· sya（绘/PV）', '2015-10-15', 'https://www.bilibili.com/video/av3061232', NULL, '["正篇","传说曲"]'::jsonb, '双向系列正篇收官之作（第九作），以61小时左右达成殿堂。延续系列悲剧美学与轮回主题：表天依夺走黑天依能力后，令自己和言和遗忘彼此、时间倒转回未犯错之前，选择不再相爱；苏醒前几世记忆的言和同时动用「重来」能力，试图结束轮回。作者称双向是「永远无法得到幸福的轮回」，但也说「一百个人有一百种解释」，本曲为开放式结局。', 'shuangxiang', NULL, '[{"image":"assets/panels/shuangxiang-yiwang-p1.jpg","caption":"正篇收官，轮回主题推向高潮。"},{"image":"assets/panels/shuangxiang-yiwang-p2.jpg","caption":"表天依令二人遗忘彼此、时间倒转，选择不再相爱。"},{"image":"assets/panels/shuangxiang-yiwang-p3.jpg","caption":"言和同时动用「重来」能力试图结束轮回——开放式结局。"}]'::jsonb, '[{"label":"投稿B站（av3061232）· 系列正篇收官·传说曲","date":"2015-10-15"},{"label":"传说曲（殿堂用时约61小时）","date":"传说达成日待核"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('nixiang-shouhu', '逆向守护', '洛天依', 'JUSF周存（曲/词/编/调）· sya（绘）· Eating DF（PV）', '2014-02-27', 'https://www.bilibili.com/video/av985798', NULL, '["角色歌","殿堂曲"]'::jsonb, '双向系列第六作，洛天依的人物番外角色歌。以极快语速搭配存式高音与黑嗓，围绕洛天依的「双重人格」设定：白人格渴望守护、黑人格怂恿杀掉言和——「你是谁？我是你。」剧情与后续《单向苏醒》直接关联。', 'shuangxiang', NULL, '[{"caption":"洛天依的人物番外，剖白其双重人格。"},{"caption":"白人格渴望被拯救与守护，黑人格怂恿杀掉言和。"},{"caption":"「你是谁？——我是你。」黑白人格的对峙。"}]'::jsonb, '[{"label":"投稿B站（av985798）· 洛天依番外角色歌","date":"2014-02-27"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('zhengxiang-qipian', '正向欺骗', '言和', 'JUSF周存（曲/词/编/调）· sya（绘/PV）', '2014-03-28', 'https://www.bilibili.com/video/BV1Bs411Z74r', NULL, '["角色歌","殿堂曲"]'::jsonb, '双向系列第七作，乐正绫的角色番外（初由言和代唱）。继承系列前作曲风，乐正绫以个人独白讲述自己的身世，歌词充满对个人世界的绝望与厌恶，也为前作埋下的情节伏笔作了解释。', 'shuangxiang', NULL, '[{"caption":"乐正绫的角色番外，以个人独白展开。"},{"caption":"讲述乐正绫的身世，充满对个人世界的绝望与厌恶。"},{"caption":"为前作埋下的情节伏笔作了解释。"}]'::jsonb, '[{"label":"投稿（专辑《双向·轮回与幸福》）· 乐正绫番外角色歌","date":"2014-03-28"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('danxiang-suxing', '单向苏醒', '洛天依、言和', 'JUSF周存（曲/词/编/调）· sya（绘）', '2014-05-22', 'https://www.bilibili.com/video/av1139245', NULL, '["角色歌","殿堂曲"]'::jsonb, '双向系列第八作，言和的角色番外（非正作）。写言和向洛天依表白后，洛天依无法控制黑向人格「杀掉言和」的怂恿而选择自杀的悲伤故事（关于自杀或同归于尽存在争议）。采用系列一贯的悲伤曲调与黑暗曲风。', 'shuangxiang', NULL, '[{"caption":"言和的角色番外，非系列正作。"},{"caption":"言和表白后，洛天依的黑向人格怂恿「杀掉言和」。"},{"caption":"洛天依在黑白人格激烈斗争后选择自杀——悲伤结局（争议）。"}]'::jsonb, '[{"label":"投稿B站（av1139245）· 言和番外角色歌","date":"2014-05-22"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shuangxiang-qingsu', '双向倾诉', '洛天依、言和', 'JUSF周存（曲/词/编/调）· Aya、sya（绘）', '2018-07-11', 'https://www.bilibili.com/video/BV1Fs411H7Cr', NULL, '["特别篇","传说曲"]'::jsonb, '双向系列第十作之特别篇（2018年，距前作近三年）。与「宙与埃」世界观有所联系，是系列的后续外传，呈现轮回交错命运下洛言两位主角可能出现的另一个结局。同时为2018年洛天依言和庆生会应援作品、存娘写给两位歌姬的第一首生日贺曲。殿堂用时2日2时4分。', 'shuangxiang', NULL, '[{"caption":"特别篇，系列时隔近三年再出新作。"},{"caption":"与「宙与埃」世界观联系，呈现轮回之下另一种可能的结局。"},{"caption":"洛天依言和庆生会应援曲，印证「双向永不完结」。"}]'::jsonb, '[{"label":"投稿（2018-07-11）· 系列特别篇·传说曲","date":"2018-07-11"},{"label":"传说曲（殿堂用时2日2时4分）","date":"传说达成日待核"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shichong-gaobie', '十重告别 Farewell.', '洛天依、言和、乐正绫、双狐座', '雨狸（策划/词）· DELA、崩坏Soviesty（曲）· 潜移默化、崩坏Soviesty（编）· 流绪、台风别打我手机（调）· POiSON（混）· Lune（曲绘）· owen-z（PV）', '2025-11-28', 'https://www.bilibili.com/video/BV1k3S7BkEag', NULL, '["十周年纪念曲","传说曲"]'::jsonb, '妄想症Paranoia系列十周年官方纪念曲（非正篇）。由洛天依、言和、乐正绫与雨狸录制的新声库「双狐座」共同演唱，串烧 remix 了《绝世丑角》《微观戏剧》《世界沉睡童话》《第一首歌》四首游戏主题曲，像角色们复盘自己的经历。引入第四面墙之外的「双狐座」元叙事视角，带领角色、创作者与听众共同回望整个系列，把苦痛与欢愉、虚构与真实都郑重收纳为继续「歌颂明天」的力量。第一首 DiffSinger 中文传说曲。', 'wangxiang', NULL, '[{"caption":"十周年纪念曲，串烧 remix 了系列四首游戏主题曲，像角色们复盘自己的经历。"},{"caption":"第四面墙之外的「双狐座」登场，带领角色、创作者与听众共同回望整个系列。"},{"caption":"把苦痛与欢愉、虚构与真实都收纳为继续「歌颂明天」的力量。"}]'::jsonb, '[{"label":"投稿B站（BV1k3S7BkEag）· 妄想症十周年纪念曲","date":"2025-11-28"},{"label":"传说曲 · 第一首 DiffSinger 中文传说曲（2026-02-18 达成）","date":"2026-02-18"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('jueti-jueming', '绝体绝命', '洛天依（乐正龙牙、阿良良木健和声）', '阿良良木健（词/曲/编/调/混）· 诗驯（曲绘）· 睡狸（PV）', '2018-04-04', 'https://www.bilibili.com/video/BV1HW411T741', NULL, '["传说曲","殿堂47时7分"]'::jsonb, '「奇爱人生（LOVE SERIES）」系列第三作（Venom），剧情上延续《春风来》，收录于阿良良木健第二张专辑《奇爱人生》。据作者所言有两个主题：一为描写抑郁症患者的内心挣扎；二为对当时 VOCALOID 文化圈的思考、批判与激励——「VOCALOID IS DEAD？」不，「VOCALOID IS ALIVE」。PV 中的「少女」与「老人」两位洛天依均在前作《亲爱的》里出现过，老人的悲剧源于《春风来》中的 HALO 病毒。传说曲，殿堂用时47时7分，曾是阿良良木健最速殿堂曲（后被《不老不死》以43时18分刷新）。', 'qiai', '{"plays":690,"asOf":"2026-10-29","note":"快照 690万（B站 view API stat.view=6896250，2026-10-29）"}'::jsonb, '[{"caption":"那一天，她从一片狼藉的研究基地里活了下来，成了唯一的幸存者，被从冷冻舱中解救回家。"},{"caption":"然而噩梦只是延续——她被诬陷为杀害同事们的罪魁祸首，以「罪犯」之名，在孤独与绝望里死去。"},{"caption":"直到那些「伙伴」们的到来：他们复活了她，称呼她为「母亲」。她以沉重的代价，与死神交换了生命。"},{"caption":"「VOCALOID IS DEAD」——那天以后，世人再没有听到过她的声音。人们都说她被「淘汰」了、「消失」了、「死」了。"},{"caption":"她被囚禁在「遗忘山丘」最深的谷底，害怕着被谁加害，渴望着被谁救援，眼睁睁看着黑暗步步逼近。"},{"caption":"这结局，看似已经注定。然而，总会有一股力量，在沉默中爆发。"}]'::jsonb, '[{"label":"投稿B站（BV1HW411T741）· LOVE SERIES 第三作","date":"2018-04-04"},{"label":"100万播放 · 传说曲（用时62日05时55分）","date":"2018-06-05"},{"label":"300万播放","date":"2021-04-18"},{"label":"500万播放","date":"2024-01-18"},{"label":"600万播放","date":"2025-06-07"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('bulao-busi', '不老不死', '洛天依', '阿良良木健（词/曲/编/调/混）· 诗驯（曲绘）· ActDeco（PV）', '2019-06-18', 'https://www.bilibili.com/video/BV1w4411G7nv', NULL, '["传说曲","殿堂43时18分","阿良良木健最速殿堂曲"]'::jsonb, '「异托邦 LOVETOPIA」系列第一作，世界观承接《奇爱人生》系列（B站简介另署「洛天依×徵羽摩柯 作品3号」，指该歌手组合的第三号企划作品，与系列序号是两回事）。讲述不死夫人澪夜的故事：她喝下以挚爱之人骨骼灰烬熬制的「青之水」获得不老不死，容颜永驻却再无法死去；千年后她的时代早已落幕，人们视她为「不祥之兆」，将她囚于「异托邦」地下深处的洞穴。讽刺的是，她的血液能使万物生长——整座乐园的繁荣，正以她的孤独为代价。传说曲，殿堂用时43时18分，为阿良良木健最速殿堂曲。', 'lovetopia', '{"plays":476,"asOf":"2026-10-29","note":"快照 476万（B站 view API stat.view=4764598，2026-10-29）"}'::jsonb, '[{"caption":"三十年前，慈善家爱德华·内姆莱斯在英国伦敦建立了「异托邦」——给全球流离失所的难民们创造的「世外天堂」。"},{"caption":"乐园里没有国界、没有隔阂，食物与生活所需终生免费，所有草木仿佛被神秘的力量施法，枝繁叶茂。"},{"caption":"「不死夫人」澪夜喝下了「青之水」——四十七种珍稀草药，与最爱之人的骨骼灰烬熬成。从此她不老不死，永无疾病。"},{"caption":"千年之后，属于她的时代早已结束。流浪街头的她被人当成神明派下的「不祥之兆」，囚禁在城市中心地下深处的洞穴，终日不可见人。"},{"caption":"两年前的一份文档记载：人们偶然发现她的血液可以使万物生长、永远维持活力——而同一时期，「异托邦」开始高速发展。"},{"caption":"当生命这件有始有终的事情失去了意义，永生，对她而言，便成了诅咒。"}]'::jsonb, '[{"label":"投稿B站（BV1w4411G7nv）· 异托邦 LOVETOPIA 第一作","date":"2019-06-18"},{"label":"100万播放 · 传说曲（用时282日00时50分）","date":"2020-03-26"},{"label":"200万播放","date":"2022-03-23"},{"label":"300万播放","date":"2023-11-28"},{"label":"400万播放","date":"2025-07-04"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
insert into songs (id, title, singer, author, date, bilibili, no_bilibili, badges, intro, series_id, heat, panels, milestones, my_story) values ('shuangxue-qiannian', '霜雪千年', '洛天依、乐正绫', 'COP（词/曲/编/调）· 奈奈（曲绘）· saiqomo（PV）', '2015-10-14', 'https://www.bilibili.com/video/BV1es41127Fd', NULL, '["传说曲","重制版2024"]'::jsonb, '「霜雪千年灯系列」第二作（首作《三千年夜行灯》音频投稿于 5sing、未投稿B站），「双面乐府」征集活动「桃花源」主题参赛曲。优美的曲调与精致的 PV，讲述鬼魅转世为人后追忆前缘的故事：姑娘误入雾中老街，于楼阁中睹物忆起三世前与那人把酒言欢的约定——那人临终前为不忘前世跳入忘川等候千年，三生三千年后转世为人，忘却前生。2024-05-31 COP 用 ACE 声库重新调校推出重制版（BV1zM4m1r7JS），重制版传说用时仅10日14时14分。', 'shuangxue-deng', '{"plays":666,"asOf":"2026-10-29","note":"快照 666万（B站 view API stat.view=6662969，2026-10-29）"}'::jsonb, '[{"caption":"春日梨花香渗入红帘深帐，姑娘被吸引着走上街头游玩赏景，随后独自撑起一叶扁舟，顺水前行。"},{"caption":"船行渐远，两岸植被由出芽转为葱茏，少顷竟如秋至泛了黄；雾霭中老街楼阁显现，街上却空无一人。"},{"caption":"楼阁院内一桌两盏琼觞皆已覆上尘土，陌生的记忆细流般淌进脑海：月色、清风疏叶、欢声笑语，还有那双含笑的眼。"},{"caption":"前世的记忆里，一人临终含笑与那眉眼淡漠的鬼魅道别；鬼魅为不忘前世跳入忘川等一千年，三生三千年后转世为人，忘却前生。"},{"caption":"恍惚间姑娘已满脸清泪——她仍会珍藏这份千年相会的记忆，相信那人终有一日会撑船来会。"},{"caption":"愿今生再相见，消融你眉间悲戚霜雪。"}]'::jsonb, '[{"label":"投稿B站（BV1es41127Fd）· 霜雪千年灯系列第二作","date":"2015-10-14"},{"label":"100万播放 · 传说曲（用时998日22时01分）","date":"2018-07-09"},{"label":"300万播放","date":"2023-05-22"},{"label":"500万播放","date":"2024-10-25"},{"label":"重制版（ACE声库，BV1zM4m1r7JS）传说用时10日14时14分","date":"2024-05-31"}]'::jsonb, '（待补——此处由站长亲自撰写，AI 不代写）') on conflict (id) do nothing;
